//! Original-language word layer (`WRD1`).
//!
//! The file is generated by `data/import_stepbible.py` from STEPBible Data
//! (TAHOT, TAGNT, TBESH and TBESG, CC BY 4.0). Layout, little-endian:
//!
//! ```text
//! header        32 bytes: magic "WRD1", version, flags, verse_count,
//!               word_count, blob_len, lex_count, morph_count, morph_blob_len
//! verse_offsets u32 * (verse_count + 1)   word-index range per verse
//! words         14 bytes each:
//!               surface_off u32, surface_len u16, strong_id u32,
//!               morph_id u16, meta u16
//! blob          UTF-8 surfaces
//! morph_offsets u32 * (morph_count + 1)
//! morph_blob    UTF-8 morphology codes
//! lex_records   48 bytes each: six (offset u32, length u32) string pairs
//! lex_blob      UTF-8 key, lemma, transliteration, morph, gloss, meaning
//! ```
//!
//! `meta` stores the language in bits 0..1 (0 Hebrew, 1 Aramaic, 2 Greek) and
//! a punctuation flag in bit 2. `morph_id == 0xFFFF` means no morphology.

use std::cmp::Ordering;

pub const WORDS_MAGIC: [u8; 4] = *b"WRD1";
pub const WORDS_HEADER_LEN: usize = 32;
pub const WORD_RECORD_LEN: usize = 14;
pub const LEX_RECORD_LEN: usize = 48;
pub const MORPH_NONE: u16 = 0xFFFF;

#[derive(Clone, Copy, Debug)]
pub struct Word {
    pub surface_off: u32,
    pub surface_len: u16,
    pub strong_id: u32,
    pub morph_id: u16,
    pub meta: u16,
}

impl Word {
    pub fn lang(self) -> u8 {
        (self.meta & 0x3) as u8
    }

    pub fn is_punctuation(self) -> bool {
        self.meta & 0x4 != 0
    }

    /// True when the verse has no NA witness and the Byzantine/TR text is
    /// shown instead.
    pub fn is_fallback(self) -> bool {
        self.meta & 0x8 != 0
    }
}

#[derive(Clone, Copy, Debug)]
struct LexRecord {
    fields: [(u32, u32); 6],
}

#[derive(Clone, Copy, Debug)]
pub struct LexView<'a> {
    pub key: &'a str,
    pub lemma: &'a str,
    pub translit: &'a str,
    pub morph: &'a str,
    pub gloss: &'a str,
    pub meaning: &'a str,
}

/// Verse-indexed words plus the brief lexicon, parsed zero-copy from an
/// uncompressed `WRD1` buffer.
#[derive(Debug, Default)]
pub struct WordsData {
    pub verse_count: u32,
    verse_offsets: Vec<u32>,
    words: Vec<Word>,
    blob: Vec<u8>,
    morph_offsets: Vec<u32>,
    morph_blob: Vec<u8>,
    lex_records: Vec<LexRecord>,
    lex_blob: Vec<u8>,
}

impl WordsData {
    pub fn parse(bytes: &[u8]) -> Result<Self, String> {
        if bytes.len() < WORDS_HEADER_LEN {
            return Err("words: file too short".into());
        }
        if bytes[0..4] != WORDS_MAGIC {
            return Err("words: bad magic (expected WRD1)".into());
        }
        let version = u16::from_le_bytes([bytes[4], bytes[5]]);
        if version != 1 {
            return Err(format!("words: unsupported version {version}"));
        }
        let verse_count = read_u32(bytes, 8)?;
        let word_count = read_u32(bytes, 12)? as usize;
        let blob_len = read_u32(bytes, 16)? as usize;
        let lex_count = read_u32(bytes, 20)? as usize;
        let morph_count = read_u32(bytes, 24)? as usize;
        let morph_blob_len = read_u32(bytes, 28)? as usize;

        let lex_len = lex_count
            .checked_mul(LEX_RECORD_LEN)
            .ok_or_else(|| "words: lexicon table overflow".to_string())?;

        let mut cursor = WORDS_HEADER_LEN;
        let verse_offsets = read_u32_vec(bytes, &mut cursor, verse_count as usize + 1)?;
        let words = read_words(bytes, &mut cursor, word_count)?;
        let blob_end = cursor
            .checked_add(blob_len)
            .ok_or_else(|| "words: blob overflow".to_string())?;
        let blob = bytes
            .get(cursor..blob_end)
            .ok_or_else(|| "words: truncated surface blob".to_string())?
            .to_vec();
        cursor = blob_end;
        let morph_offsets = read_u32_vec(bytes, &mut cursor, morph_count + 1)?;
        let morph_end = cursor
            .checked_add(morph_blob_len)
            .ok_or_else(|| "words: morphology blob overflow".to_string())?;
        let morph_blob = bytes
            .get(cursor..morph_end)
            .ok_or_else(|| "words: truncated morphology blob".to_string())?
            .to_vec();
        cursor = morph_end;

        let lex_records_end = cursor
            .checked_add(lex_len)
            .ok_or_else(|| "words: lexicon overflow".to_string())?;
        let lex_records = read_lex_records(
            bytes
                .get(cursor..lex_records_end)
                .ok_or_else(|| "words: truncated lexicon table".to_string())?,
            lex_count,
        )?;
        cursor = lex_records_end;
        let lex_blob = bytes
            .get(cursor..)
            .ok_or_else(|| "words: truncated lexicon blob".to_string())?
            .to_vec();

        if verse_offsets.first().copied() != Some(0)
            || verse_offsets.last().copied() != Some(word_count as u32)
        {
            return Err("words: verse offsets do not partition the word table".into());
        }
        for pair in verse_offsets.windows(2) {
            if pair[1] < pair[0] {
                return Err("words: verse offsets are not monotonic".into());
            }
        }
        if morph_offsets.first().copied() != Some(0)
            || morph_offsets.last().copied() != Some(morph_blob_len as u32)
        {
            return Err("words: morphology offsets do not cover the blob".into());
        }
        for pair in morph_offsets.windows(2) {
            if pair[1] < pair[0] {
                return Err("words: morphology offsets are not monotonic".into());
            }
        }

        let data = Self {
            verse_count,
            verse_offsets,
            words,
            blob,
            morph_offsets,
            morph_blob,
            lex_records,
            lex_blob,
        };
        data.validate()?;
        Ok(data)
    }

    fn validate(&self) -> Result<(), String> {
        for (index, word) in self.words.iter().enumerate() {
            let start = word.surface_off as usize;
            let end = start
                .checked_add(word.surface_len as usize)
                .ok_or_else(|| format!("words: surface overflow at word {index}"))?;
            let surface = self
                .blob
                .get(start..end)
                .ok_or_else(|| format!("words: bad surface range at word {index}"))?;
            std::str::from_utf8(surface)
                .map_err(|_| format!("words: surface is not UTF-8 at word {index}"))?;
            if word.strong_id as usize >= self.lex_records.len() {
                return Err(format!("words: bad Strong id at word {index}"));
            }
            if word.morph_id != MORPH_NONE
                && usize::from(word.morph_id) >= self.morph_offsets.len() - 1
            {
                return Err(format!("words: bad morphology id at word {index}"));
            }
        }
        for index in 0..self.lex_records.len() {
            let record = self.lex_records[index];
            for (part, (offset, length)) in record.fields.iter().enumerate() {
                let start = *offset as usize;
                let end = start
                    .checked_add(*length as usize)
                    .ok_or_else(|| format!("words: lexicon range overflow at entry {index}"))?;
                let text = self
                    .lex_blob
                    .get(start..end)
                    .ok_or_else(|| format!("words: bad lexicon range at entry {index}/{part}"))?;
                std::str::from_utf8(text)
                    .map_err(|_| format!("words: lexicon text is not UTF-8 at {index}/{part}"))?;
            }
        }
        Ok(())
    }

    pub fn word_count(&self) -> usize {
        self.words.len()
    }

    pub fn lex_count(&self) -> usize {
        self.lex_records.len()
    }

    pub fn words_in_verse(&self, verse: u32) -> &[Word] {
        if verse >= self.verse_count {
            return &[];
        }
        let start = self.verse_offsets[verse as usize] as usize;
        let end = self.verse_offsets[verse as usize + 1] as usize;
        &self.words[start..end]
    }

    pub fn surface(&self, word: &Word) -> Option<&str> {
        let start = word.surface_off as usize;
        let end = start + word.surface_len as usize;
        std::str::from_utf8(self.blob.get(start..end)?).ok()
    }

    pub fn morph(&self, word: &Word) -> Option<&str> {
        if word.morph_id == MORPH_NONE {
            return None;
        }
        let index = word.morph_id as usize;
        let start = *self.morph_offsets.get(index)? as usize;
        let end = *self.morph_offsets.get(index + 1)? as usize;
        std::str::from_utf8(self.morph_blob.get(start..end)?).ok()
    }

    fn lex_str(&self, (offset, length): (u32, u32)) -> Option<&str> {
        let start = offset as usize;
        let end = start + length as usize;
        std::str::from_utf8(self.lex_blob.get(start..end)?).ok()
    }

    pub fn lex(&self, id: u32) -> Option<LexView<'_>> {
        let record = self.lex_records.get(id as usize)?;
        Some(LexView {
            key: self.lex_str(record.fields[0])?,
            lemma: self.lex_str(record.fields[1])?,
            translit: self.lex_str(record.fields[2])?,
            morph: self.lex_str(record.fields[3])?,
            gloss: self.lex_str(record.fields[4])?,
            meaning: self.lex_str(record.fields[5])?,
        })
    }

    /// Binary search by Strong key (`G0025`, `H7225G`, ...).
    pub fn lex_id(&self, key: &str) -> Option<u32> {
        let mut low = 0usize;
        let mut high = self.lex_records.len();
        while low < high {
            let middle = low + (high - low) / 2;
            let current = self.lex(middle as u32)?.key;
            match current.cmp(key) {
                Ordering::Less => low = middle + 1,
                Ordering::Greater => high = middle,
                Ordering::Equal => return Some(middle as u32),
            }
        }
        None
    }

    /// Every verse containing at least one word with this Strong id.
    pub fn occurrences(&self, strong_id: u32) -> Vec<u32> {
        let mut verses = Vec::new();
        for verse in 0..self.verse_count {
            if self
                .words_in_verse(verse)
                .iter()
                .any(|word| word.strong_id == strong_id)
            {
                verses.push(verse);
            }
        }
        verses
    }

    pub fn occurrence_count(&self, strong_id: u32) -> usize {
        self.occurrences(strong_id).len()
    }

    /// Language of the first word in a verse (0 Hebrew, 1 Aramaic, 2 Greek).
    pub fn verse_language(&self, verse: u32) -> Option<u8> {
        self.words_in_verse(verse).first().map(|word| word.lang())
    }

    /// True when the verse falls back to the Byzantine/TR text.
    pub fn verse_is_fallback(&self, verse: u32) -> bool {
        self.words_in_verse(verse)
            .first()
            .is_some_and(|word| word.is_fallback())
    }
}

fn read_u32(bytes: &[u8], at: usize) -> Result<u32, String> {
    let slice = bytes
        .get(at..at + 4)
        .ok_or_else(|| "words: unexpected end of file".to_string())?;
    Ok(u32::from_le_bytes([slice[0], slice[1], slice[2], slice[3]]))
}

fn read_u32_vec(bytes: &[u8], cursor: &mut usize, count: usize) -> Result<Vec<u32>, String> {
    let length = count
        .checked_mul(4)
        .ok_or_else(|| "words: length overflow".to_string())?;
    let end = cursor
        .checked_add(length)
        .ok_or_else(|| "words: length overflow".to_string())?;
    let slice = bytes
        .get(*cursor..end)
        .ok_or_else(|| "words: unexpected end of file".to_string())?;
    let mut out = Vec::with_capacity(count);
    for chunk in slice.chunks_exact(4) {
        out.push(u32::from_le_bytes([chunk[0], chunk[1], chunk[2], chunk[3]]));
    }
    *cursor = end;
    Ok(out)
}

fn read_words(bytes: &[u8], cursor: &mut usize, count: usize) -> Result<Vec<Word>, String> {
    let length = count
        .checked_mul(WORD_RECORD_LEN)
        .ok_or_else(|| "words: word table overflow".to_string())?;
    let end = cursor
        .checked_add(length)
        .ok_or_else(|| "words: word table overflow".to_string())?;
    let slice = bytes
        .get(*cursor..end)
        .ok_or_else(|| "words: truncated word table".to_string())?;
    let mut out = Vec::with_capacity(count);
    for chunk in slice.chunks_exact(WORD_RECORD_LEN) {
        out.push(Word {
            surface_off: u32::from_le_bytes([chunk[0], chunk[1], chunk[2], chunk[3]]),
            surface_len: u16::from_le_bytes([chunk[4], chunk[5]]),
            strong_id: u32::from_le_bytes([chunk[6], chunk[7], chunk[8], chunk[9]]),
            morph_id: u16::from_le_bytes([chunk[10], chunk[11]]),
            meta: u16::from_le_bytes([chunk[12], chunk[13]]),
        });
    }
    *cursor = end;
    Ok(out)
}

fn read_lex_records(bytes: &[u8], count: usize) -> Result<Vec<LexRecord>, String> {
    let expected = count
        .checked_mul(LEX_RECORD_LEN)
        .ok_or_else(|| "words: lexicon table overflow".to_string())?;
    if bytes.len() != expected {
        return Err("words: lexicon table has the wrong size".into());
    }
    let mut out = Vec::with_capacity(count);
    for chunk in bytes.chunks_exact(LEX_RECORD_LEN) {
        let mut fields = [(0u32, 0u32); 6];
        for (index, field) in fields.iter_mut().enumerate() {
            let at = index * 8;
            *field = (
                u32::from_le_bytes([chunk[at], chunk[at + 1], chunk[at + 2], chunk[at + 3]]),
                u32::from_le_bytes([chunk[at + 4], chunk[at + 5], chunk[at + 6], chunk[at + 7]]),
            );
        }
        out.push(LexRecord { fields });
    }
    Ok(out)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn push_str(blob: &mut Vec<u8>, text: &str) -> (u32, u32) {
        let offset = blob.len() as u32;
        blob.extend_from_slice(text.as_bytes());
        (offset, text.len() as u32)
    }

    #[test]
    fn parse_minimal_word_file() {
        let mut lex_blob = Vec::new();
        let key = push_str(&mut lex_blob, "G0001");
        let lemma = push_str(&mut lex_blob, "α");
        let translit = push_str(&mut lex_blob, "a");
        let morph_text = push_str(&mut lex_blob, "N-NSF");
        let gloss = push_str(&mut lex_blob, "alpha");
        let meaning = push_str(&mut lex_blob, "first");
        let lex_fields = [key, lemma, translit, morph_text, gloss, meaning];

        let mut lex_record = Vec::new();
        for (offset, length) in lex_fields {
            lex_record.extend_from_slice(&offset.to_le_bytes());
            lex_record.extend_from_slice(&length.to_le_bytes());
        }

        let mut bytes = Vec::new();
        bytes.extend_from_slice(&WORDS_MAGIC);
        bytes.extend_from_slice(&1u16.to_le_bytes());
        bytes.extend_from_slice(&0u16.to_le_bytes());
        bytes.extend_from_slice(&1u32.to_le_bytes()); // verses
        bytes.extend_from_slice(&1u32.to_le_bytes()); // words
        bytes.extend_from_slice(&2u32.to_le_bytes()); // surface blob
        bytes.extend_from_slice(&1u32.to_le_bytes()); // lexicon entries
        bytes.extend_from_slice(&1u32.to_le_bytes()); // morphology codes
        bytes.extend_from_slice(&5u32.to_le_bytes()); // morphology blob
        bytes.extend_from_slice(&0u32.to_le_bytes()); // verse offset 0
        bytes.extend_from_slice(&1u32.to_le_bytes()); // verse offset 1
        bytes.extend_from_slice(&0u32.to_le_bytes()); // surface offset
        bytes.extend_from_slice(&2u16.to_le_bytes()); // surface length
        bytes.extend_from_slice(&0u32.to_le_bytes()); // strong id
        bytes.extend_from_slice(&0u16.to_le_bytes()); // morph id
        bytes.extend_from_slice(&2u16.to_le_bytes()); // Greek
        bytes.extend_from_slice("α".as_bytes());
        bytes.extend_from_slice(&0u32.to_le_bytes());
        bytes.extend_from_slice(&5u32.to_le_bytes());
        bytes.extend_from_slice(b"N-NSF");
        bytes.extend_from_slice(&lex_record);
        bytes.extend_from_slice(&lex_blob);

        let data = WordsData::parse(&bytes).expect("minimal file parses");
        assert_eq!(data.verse_count, 1);
        assert_eq!(data.word_count(), 1);
        let word = data.words_in_verse(0)[0];
        assert_eq!(data.surface(&word), Some("α"));
        assert_eq!(data.morph(&word), Some("N-NSF"));
        assert_eq!(data.verse_language(0), Some(2));
        let entry = data.lex(0).expect("lexicon entry");
        assert_eq!(entry.key, "G0001");
        assert_eq!(entry.lemma, "α");
        assert_eq!(entry.meaning, "first");
        assert_eq!(data.lex_id("G0001"), Some(0));
        assert_eq!(data.occurrences(0), vec![0]);
    }
}
